main_section_html:
{% set today = frappe.utils.get_datetime() %}
{% set today = frappe.utils.add_to_date(today, hours=0, minutes=0, seconds=0, as_datetime=True) %}
<!-- Retrieve the current user's Employee record -->
{% set Employee = (frappe.get_all('Employee', filters={'user_id': frappe.session.user}, fields=['*']))[0] %}
<!-- Find the current Payroll Period based on today's date -->
{% set Payroll_Period = (frappe.get_all('Payroll Period', filters={'start_date': ['<=', today],'end_date':['>=', today]},fields=['name','start_date', 'end_date']))[0] %}
{% set Empleado = Employee.employee %}
{% set Nombre = Employee.first_name %}
<!-- Retrieve sales targets within the current Payroll Period -->
{% set Sales_Targets = frappe.get_all('Sales Targets', 
    filters={'sales_target_date': ['between', [Payroll_Period.start_date, Payroll_Period.end_date]]}, 
    fields=["*"],
    order_by='outlet_name'
) %}
<!-- Retrieve sales commissions for the current Payroll Period -->
{% set Sales_Commissions = frappe.get_list('Sales Commissions', 
    filters={'payroll_period':['=', Payroll_Period.name]},
    fields=["*"]
)[0] %}
<!-- Retrieve commission details for the current employee within the current sales commissions record -->
{% set Employee_Commissions_Details = frappe.get_all("Employee Commissions Details",
    filters={"parent": ["=", Sales_Commissions.name],'employee':['=', Empleado]},
    fields=["*"]
)[0] %}
{% if bool(Employee_Commissions_Details) %}
    {% set store_commission_rate = Employee_Commissions_Details.store_commission_rate %}
    {% set total_hours  = Employee_Commissions_Details.total_hours  %}
    {% set total_store_commission = Employee_Commissions_Details.total_store_commission %}
    {% set store_commission_rate = Employee_Commissions_Details.store_commission_rate %}
    {% set total_personal_sales =  Employee_Commissions_Details.total_personal_sales %}
    {% set personal_commission_rate  = Employee_Commissions_Details.personal_commission_rate  %}
    {% set total_personal_commission = Employee_Commissions_Details.total_personal_commission %}
{% else %}
    {% set store_commission_rate = 0 %}
    {% set total_hours  = 0 %}
    {% set total_store_commission = 0 %}
    {% set store_commission_rate = 0 %}
    {% set total_personal_sales =  0 %}
    {% set personal_commission_rate  = 0  %}
    {% set total_personal_commission = 0 %}
{% endif %}

<!-- Initialize namespace variables for total sales target and actual sales -->
{% set ns = namespace() %}
{% set ns.sales_target = 0 %}
{% set ns.actual_sales = 0 %}

    <h2>Hello {{Nombre}}, this are today's Goals</h2>
    <table border="1">
        <thead>
            <tr>
                <th class="title">Outlet Name</th>
                <th class="title">Sales Target</th>
                <th class="title">Actual Sales</th>
                <th class="title">Difference</th>
                <th class="title">Status</th>
            </tr>
        </thead>
        <tbody>
            <!-- Loop through each sales target to display them -->
            {% for salegoal in Sales_Targets %}
                {% set date_string = today.strftime('%Y-%m-%d') %}
                {% set today_date_string = salegoal.sales_target_date.strftime('%Y-%m-%d') %}
                {% if today_date_string == date_string %}
                    {% set ns.sales_target = ns.sales_target + salegoal.sales_target %}
                    {% set ns.actual_sales = ns.actual_sales + salegoal.actual_sales %}
                    <tr>
                        <td id="outlet-{{loop.index0+1}}" class="outlet">{{ salegoal.outlet_name }}</td>
                        <td id="target-{{loop.index0+1}}" class="target">${{ "%.0f"|format(salegoal.sales_target) }}</td>
                        <td id="actual-{{loop.index0+1}}" class="actual">${{ "%.0f"|format(salegoal.actual_sales) }}</td>
                        <!-- Calculate difference and display status accordingly -->
                        {% if (salegoal.sales_target - salegoal.actual_sales) > 0 %}
                            <td class="difference">${{ "%.0f"|format(salegoal.sales_target - salegoal.actual_sales) }}</td>
                            
                            <td class="togo">
                            <div class="progress-container">
                                  <div class="progress-bar" id="progress-bar-{{loop.index0+1}}" style="width: 0%;">0%</div>
                            </div>
                        
                                </td>
                            
                        {% else %}
                            <td class="over">+ ${{ "%.0f"|format(salegoal.actual_sales - salegoal.sales_target) }}</td>
                            <td class="over">Over &#x1F601;</td>
                        {% endif %}
                    </tr>
                {% endif %}
            {% endfor %}
            <!-- Display total sales target vs actual sales -->
            <tr>
                <td id="outlet-0" class="outlet">CRAFTED</td>
                <td id="target-0" class="target">${{ "%.0f"|format(ns.sales_target) }}</td>
                <td id="actual-0" class="actual">${{ "%.0f"|format(ns.actual_sales) }}</td>
                {% if (ns.sales_target - ns.actual_sales) > 0 %}
                    <td class="difference">${{ "%.0f"|format(ns.sales_target - ns.actual_sales) }}</td>
                    <td class="togo"> <div class="progress-container">
                                  <div class="progress-bar" id="progress-bar-0" style="width: 0%;">0%</div>
                            </div></td>
                {% else %}
                    <td class="over">+ ${{ "%.0f"|format(ns.actual_sales - ns.sales_target) }}</td>
                    <td class="over">Over &#x1F601;</td>
                {% endif %}
            </tr>
            <tr><td class="footer" colspan="5">Actuals are updated every hour</td></tr>
        </tbody>
    </table>

