document.addEventListener("DOMContentLoaded", function() {
    var targets = document.getElementsByClassName('target');
    var actuals = document.getElementsByClassName('actual'); // Corrected class name

    for (var i = 0; i < targets.length; i++) {
        let barid = (targets[i].id).split("-")[1]
        console.log(targets[i].id); // Prints the text content of each target element
        console.log(barid); // Prints the current index

        // Ensure parsing as numbers and calculate percentage
        let percentage = (parseFloat(actuals[i].textContent.replace("$","")) / parseFloat(targets[i].textContent.replace("$",""))) * 100;
            console.log(percentage)
            console.log(actuals[i].textContent.replace("$","")) 
            console.log(targets[i].textContent)
        // Retrieve the corresponding progress bar for each pair of target and actual
        let progressBar = document.getElementById('progress-bar-' + barid);
        if (progressBar) { // Check if progressBar exists
            console.log(progressBar.id)
            progressBar.style.width = percentage + '%';
            progressBar.textContent =  percentage.toFixed(0) +  ' %'; // Fixed to show up to 2 decimal places

            // Change the color if above 85%
            if (percentage > 75) {
                progressBar.classList.add('over-75');
            }
            if (percentage > 90) {
                progressBar.classList.add('over-90');
            }
        }
    }
});

